    void StyleHud(){var canvas=hudRoot.GetComponent<Canvas>();if(canvas)canvas.sortingOrder=10;hud.font=UIFont();hud.fontSize=18;hud.fontStyle=FontStyle.Bold;hud.color=new Color(.87f,.95f,1f);hud.alignment=TextAnchor.MiddleCenter;var panel=hud.transform.parent?hud.transform.parent.GetComponent<Image>():null;if(panel)panel.color=new Color(.018f,.035f,.075f,.96f);if(hud.transform.parent&&!hud.transform.parent.Find("HudAccent"))AddHudAccent(hud.transform.parent,"HudAccent",new Vector2(0,-82),new Vector2(1920,3),new Color(.04f,.72f,.92f));}
