    void CreateGuardVisionCones(){for(int i=0;i<guards.Count;i++){if(guardCones[i])continue;var cone=new GameObject("Cono de visión · profesora");guardCones[i]=cone;var filter=cone.AddComponent<MeshFilter>();var renderer=cone.AddComponent<MeshRenderer>();var mesh=new Mesh();const int segments=32;var vertices=new Vector3[segments+2];var triangles=new int[segments*3];vertices[0]=new Vector3(0,.035f,0);float half=VisionAngle()*.5f*Mathf.Deg2Rad;for(int j=0;j<=segments;j++){float a=-half+2*half*j/segments;vertices[j+1]=new Vector3(Mathf.Sin(a)*VisionRange(),.035f,Mathf.Cos(a)*VisionRange());if(j<segments){int k=j*3;triangles[k]=0;triangles[k+1]=j+1;triangles[k+2]=j+2;}}mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();filter.mesh=mesh;var mat=new Material(Shader.Find("Sprites/Default"));mat.color=new Color(1f,.34f,.13f,.2f);renderer.material=mat;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;}}
