    void ReturnChasingGuards(){for(int i=0;i<guards.Count;i++){guardIgnorePlayerUntil[i]=Time.time+3f;if(guardChasing[i]){guardChasing[i]=false;guardReturning[i]=true;guardSearch[i]=0;}}}
    void UpdateGuards(){float patrolRate=difficulty==Difficulty.PeligroInminente?1.25f:difficulty==Difficulty.Avanzado?.9f:.65f;float viewRange=VisionRange(),halfAngle=VisionAngle()*.5f;bool anyoneSearching=false;for(int i=0;i<guards.Count;i++){var g=guards[i];if(!g)continue;Vector3 home=guardHome[i];float t=Time.time*patrolRate+i*2.4f;Vector3 patrolPosition=new Vector3(home.x+Mathf.Sin(t)*5,0,home.z+Mathf.Cos(t*.7f)*1.2f);Vector3 patrolDirection=new Vector3(Mathf.Cos(t)*5,0,-Mathf.Sin(t*.7f)*.84f).normalized;
            if(guardReturning[i]){Vector3 toHome=home-g.transform.position;toHome.y=0;if(toHome.sqrMagnitude>.01f){g.transform.position=Vector3.MoveTowards(g.transform.position,home,8f*Time.deltaTime);UpdateVisionCone(i,g.transform.position,toHome,false);continue;}guardReturning[i]=false;g.transform.position=home;}
            if(!guardChasing[i])g.transform.position=patrolPosition;Vector3 toPlayer=player.transform.position-g.transform.position;toPlayer.y=0;float distance=toPlayer.magnitude;float angle=toPlayer.sqrMagnitude>.001f?Vector3.Angle(patrolDirection,toPlayer):180f;if(!playerHidden&&Time.time>=guardIgnorePlayerUntil[i]&&distance<=viewRange&&angle<=halfAngle){guardChasing[i]=true;guardLastSeen[i]=player.transform.position;guardSearch[i]=3.5f;}
            if(guardChasing[i]){anyoneSearching=true;if(!playerHidden){guardLastSeen[i]=player.transform.position;guardSearch[i]=3.5f;}else guardSearch[i]-=Time.deltaTime;Vector3 target=playerHidden?guardLastSeen[i]:player.transform.position;Vector3 chase=target-g.transform.position;chase.y=0;float chaseSpeed=difficulty==Difficulty.Principiante?7f:difficulty==Difficulty.Avanzado?9f:11f;if(chase.sqrMagnitude>.16f)g.transform.position=Vector3.MoveTowards(g.transform.position,new Vector3(target.x,0,target.z),chaseSpeed*Time.deltaTime);if(playerHidden&&chase.magnitude<.65f&&guardSearch[i]<=0)guardChasing[i]=false;if(!playerHidden&&distance<.78f&&hitCooldown<=0){lives--;hitCooldown=1.5f;ReturnChasingGuards();player.transform.position=handoff==0?new Vector3(-14,0,0):relay[handoff-1];message="¡Te alcanzó la profesora! Perdiste una vida.";if(lives<=0)Lose();}}
