        if(id==4){Tri(t,11,82,27,82,12,109,fur);Tri(t,37,82,53,82,52,109,fur);Rect(t,18,48,28,5,new Color(.78f,.12f,.18f));Rect(t,21,5,9,29,new Color(.13f,.16f,.21f));Rect(t,34,5,9,29,new Color(.13f,.16f,.21f));Rect(t,22,40,22,30,new Color(.08f,.12f,.22f));Rect(t,19,53,26,4,new Color(.87f,.84f,.78f));Rect(t,24,49,5,5,new Color(.84f,.13f,.19f));}
