    void Disc(Texture2D t,int cx,int cy,int r,Color c){for(int y=-r;y<=r;y++)for(int x=-r;x<=r;x++)if(x*x+y*y<=r*r&&cx+x>=0&&cx+x<t.width&&cy+y>=0&&cy+y<t.height)t.SetPixel(cx+x,cy+y,c);}
    void Rect(Texture2D t,int x,int y,int w,int h,Color c){for(int a=x;a<x+w;a++)for(int b=y;b<y+h;b++)if(a>=0&&a<t.width&&b>=0&&b<t.height)t.SetPixel(a,b,c);}
    void Tri(Texture2D t,int x1,int y1,int x2,int y2,int x3,int y3,Color c){for(int y=y1;y<=y3;y++){float k=(y-y1)/(float)Mathf.Max(1,y3-y1);int a=Mathf.RoundToInt(Mathf.Lerp(x1,x3,k)),b=Mathf.RoundToInt(Mathf.Lerp(x2,x3,k));Rect(t,Mathf.Min(a,b),y,Mathf.Abs(b-a)+1,1,c);}}
    void CreateUI(){var go=new GameObject("HUD");var canvas=go.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=10;go.AddComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;go.AddComponent<GraphicRaycaster>();var panel=new GameObject("Panel");panel.transform.SetParent(go.transform,false);var im=panel.AddComponent<Image>();im.color=new Color(.018f,.035f,.075f,.95f);var rt=panel.GetComponent<RectTransform>();rt.anchorMin=new Vector2(0,1);rt.anchorMax=new Vector2(1,1);rt.pivot=new Vector2(.5f,1);rt.sizeDelta=new Vector2(0,84);var tx=new GameObject("Estado");tx.transform.SetParent(panel.transform,false);hud=tx.AddComponent<Text>();hud.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");hud.fontSize=18;hud.fontStyle=FontStyle.Bold;hud.color=new Color(.88f,.96f,1f);hud.alignment=TextAnchor.MiddleCenter;tx.GetComponent<RectTransform>().anchorMin=Vector2.zero;tx.GetComponent<RectTransform>().anchorMax=Vector2.one;tx.GetComponent<RectTransform>().offsetMin=new Vector2(20,8);tx.GetComponent<RectTransform>().offsetMax=new Vector2(-20,-8);hudRoot=go;AddHudAccent(panel.transform,"HudTopAccent",new Vector2(0,-82),new Vector2(1920,3),new Color(.04f,.72f,.92f));CreateMenu();}
