    Text AddMenuText(Transform parent,string value,int size,Vector2 pos,Vector2 box,TextAnchor alignment=TextAnchor.MiddleCenter){var o=new GameObject("Text");o.transform.SetParent(parent,false);var t=o.AddComponent<Text>();t.font=UIFont();t.text=value;t.fontSize=size;t.fontStyle=size>=20?FontStyle.Bold:FontStyle.Normal;t.color=Color.white;t.alignment=alignment;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;var sh=o.AddComponent<Shadow>();sh.effectColor=new Color(0,0,0,.65f);sh.effectDistance=new Vector2(1,-2);var r=o.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=box;r.anchoredPosition=pos;return t;}
    void CreateMenu(){EnsureEventSystem();if(menuRoot)return;menuRoot=GameObject.Find("Main Menu UI");if(menuRoot){var savedCard=menuRoot.transform.Find("Panel principal");if(savedCard)menuCard=savedCard.GetComponent<RectTransform>();var savedBg=menuRoot.transform.Find("Fondo");if(savedBg){var im=savedBg.GetComponent<Image>();if(im){im.sprite=MakeMenuBackdrop();im.color=Color.white;}}DecorateMenu();return;}menuRoot=new GameObject("Main Menu UI");var canvas=menuRoot.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=30;menuRoot.AddComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;menuRoot.AddComponent<GraphicRaycaster>();var bg=new GameObject("Fondo");bg.transform.SetParent(menuRoot.transform,false);var bgImage=bg.AddComponent<Image>();bgImage.sprite=MakeMenuBackdrop();bgImage.color=Color.white;bgImage.raycastTarget=false;var br=bg.GetComponent<RectTransform>();br.anchorMin=Vector2.zero;br.anchorMax=Vector2.one;br.offsetMin=br.offsetMax=Vector2.zero;var card=new GameObject("Panel principal");card.transform.SetParent(menuRoot.transform,false);var ci=card.AddComponent<Image>();ci.color=new Color(.025f,.045f,.09f,.96f);var edge=card.AddComponent<Outline>();edge.effectColor=new Color(.04f,.66f,.85f,.9f);edge.effectDistance=new Vector2(2,2);menuCard=card.GetComponent<RectTransform>();menuCard.anchorMin=menuCard.anchorMax=new Vector2(.5f,.5f);menuCard.sizeDelta=new Vector2(820,900);DecorateMenu();ShowMainMenu();}
    Sprite MakeMenuBackdrop(){const int n=320;var t=new Texture2D(n,n,TextureFormat.RGBA32,false);t.filterMode=FilterMode.Bilinear;t.wrapMode=TextureWrapMode.Clamp;var p=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float u=x/(float)n,v=y/(float)n;float vignette=Mathf.Clamp01(1f-Mathf.Sqrt((u-.5f)*(u-.5f)+(v-.5f)*(v-.5f))*.8f);Color c=Color.Lerp(new Color(.012f,.025f,.07f),new Color(.075f,.025f,.12f),v);if(x%40<2||y%40<2)c=Color.Lerp(c,new Color(.05f,.47f,.67f),.14f);if((x+y*2)%157<3)c=Color.Lerp(c,new Color(.86f,.08f,.34f),.2f);p[y*n+x]=c*vignette;}t.SetPixels(p);t.Apply();return Sprite.Create(t,new Rect(0,0,n,n),new Vector2(.5f,.5f),100);}
    void DecorateMenu(){if(!menuRoot||menuRoot.transform.Find("Marco visual"))return;var frame=new GameObject("Marco visual");frame.transform.SetParent(menuRoot.transform,false);frame.transform.SetAsLastSibling();AddFrameRect(frame.transform,"Borde superior",new Vector2(0,450),new Vector2(820,4),new Color(.05f,.78f,.94f));AddFrameRect(frame.transform,"Borde inferior",new Vector2(0,-450),new Vector2(820,4),new Color(.94f,.13f,.42f));AddFrameRect(frame.transform,"Borde izquierdo",new Vector2(-410,0),new Vector2(3,900),new Color(.05f,.44f,.7f));AddFrameRect(frame.transform,"Borde derecho",new Vector2(410,0),new Vector2(3,900),new Color(.05f,.44f,.7f));var brand=AddMenuText(frame.transform,"P14  //  CAMPUS NOCTURNO",12,new Vector2(-225,418),new Vector2(330,24),TextAnchor.MiddleLeft);brand.color=new Color(.3f,.84f,.96f);brand.fontStyle=FontStyle.Bold;var tag=AddMenuText(frame.transform,"STEALTH  •  ACTION  •  COMEDY",11,new Vector2(225,418),new Vector2(330,24),TextAnchor.MiddleRight);tag.color=new Color(1f,.35f,.62f);}
    void AddFrameRect(Transform parent,string name,Vector2 pos,Vector2 size,Color color){var o=new GameObject(name);o.transform.SetParent(parent,false);var image=o.AddComponent<Image>();image.color=color;image.raycastTarget=false;var r=o.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=size;r.anchoredPosition=pos;}
