    Button CreateMenuButton(string label,Vector2 pos,UnityEngine.Events.UnityAction action){var o=new GameObject(label);o.transform.SetParent(menuCard,false);var image=o.AddComponent<Image>();image.color=new Color(.025f,.075f,.14f,1);var button=o.AddComponent<Button>();button.targetGraphic=image;var colors=button.colors;colors.normalColor=new Color(.025f,.075f,.14f);colors.highlightedColor=new Color(.035f,.29f,.4f);colors.pressedColor=new Color(.06f,.53f,.64f);button.colors=colors;button.onClick.AddListener(action);var outline=o.AddComponent<Outline>();outline.effectColor=new Color(.04f,.5f,.67f,.8f);outline.effectDistance=new Vector2(1.5f,1.5f);var r=o.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(510,60);r.anchoredPosition=pos;AddMenuText(o.transform,label,21,Vector2.zero,new Vector2(480,54));var bar=new GameObject("Acento");bar.transform.SetParent(o.transform,false);var bi=bar.AddComponent<Image>();bi.color=new Color(.08f,.82f,.93f);bi.raycastTarget=false;var br=bar.GetComponent<RectTransform>();br.anchorMin=br.anchorMax=new Vector2(0,.5f);br.sizeDelta=new Vector2(5,48);br.anchoredPosition=new Vector2(12,0);return button;}
    void ClearMenu(){for(int i=menuCard.childCount-1;i>=0;i--)Destroy(menuCard.GetChild(i).gameObject);}
    void MenuHeader(string title,string subtitle){ClearMenu();var kicker=AddMenuText(menuCard,"P14  /  CAMPUS NOCTURNO",12,new Vector2(0,388),new Vector2(700,26));kicker.color=new Color(.2f,.83f,.95f);kicker.fontStyle=FontStyle.Bold;var heading=AddMenuText(menuCard,title,title=="PASILLO 14"?54:40,new Vector2(0,335),new Vector2(740,72));if(title=="PASILLO 14"){heading.color=new Color(.45f,.9f,1f);heading.fontStyle=FontStyle.Bold;}AddMenuText(menuCard,subtitle,17,new Vector2(0,286),new Vector2(730,52));AddFrameRect(menuCard,"Línea de sección",new Vector2(0,246),new Vector2(610,2),new Color(.09f,.48f,.63f));}
    void ShowMainMenu(){if(!menuRoot)return;menuRoot.SetActive(true);if(hudRoot)hudRoot.SetActive(false);gameStarted=false;MenuHeader("PASILLO 14","UNIVERSIDAD DE LOS IMPOSIBLES  ·  ENTREGA EL PROYECTO SIN QUE TE ATRAPEN");defaultPlayButton=CreateMenuButton("INICIAR PARTIDA",new Vector2(0,205),StartGame);CreateMenuButton("DIFICULTAD",new Vector2(0,125),ShowDifficulty);CreateMenuButton("PREMIOS DESBLOQUEADOS",new Vector2(0,45),ShowAwards);CreateMenuButton("PERSONAJES",new Vector2(0,-35),()=>ShowCharacter(0));CreateMenuButton("CRÉDITOS",new Vector2(0,-115),ShowCredits);AddMenuText(menuCard,"ENTER / ESPACIO JUGAR  ·  1 DIFICULTAD  ·  2 PREMIOS  ·  3 PERSONAJES  ·  4 CRÉDITOS\nWASD / FLECHAS MOVER  ·  E RELEVO  ·  ESPACIO DISTRACTOR  ·  V IMPULSO",13,new Vector2(0,-270),new Vector2(760,55));if(EventSystem.current&&defaultPlayButton)EventSystem.current.SetSelectedGameObject(defaultPlayButton.gameObject);}
    void ShowDifficulty(){MenuHeader("ELIGE DIFICULTAD","Más alcance enemigo y menos tiempo en refugio: 10 s, 7 s o 5 s.");CreateMenuButton("PRINCIPIANTE  ·  10 S EN REFUGIO  ·  TROFEO DE PLATA",new Vector2(0,150),()=>SetDifficulty(Difficulty.Principiante));CreateMenuButton("AVANZADO  ·  7 S EN REFUGIO  ·  TROFEO DE ORO",new Vector2(0,65),()=>SetDifficulty(Difficulty.Avanzado));CreateMenuButton("PELIGRO INMINENTE  ·  5 S EN REFUGIO  ·  DIAMANTE",new Vector2(0,-20),()=>SetDifficulty(Difficulty.PeligroInminente));AddMenuText(menuCard,"SELECCIÓN ACTUAL: "+difficulty.ToString().ToUpper(),18,new Vector2(0,-105),new Vector2(700,45));CreateMenuButton("VOLVER",new Vector2(0,-210),ShowMainMenu);}
    void SetDifficulty(Difficulty value){difficulty=value;ShowDifficulty();}
    void ShowAwards(){MenuHeader("VITRINA DE PREMIOS","Se guardan en este equipo entre partidas.");string[] keys={"Pasillo14_Plata","Pasillo14_Oro","Pasillo14_Diamante","Pasillo14_Consuelo"};string[] labels={"🥈 TROFEO DE PLATA","🥇 TROFEO DE ORO","💎 TROFEO DE DIAMANTE","🩱 SHREK EN BIKINI"};string text="";for(int i=0;i<keys.Length;i++)text+=PlayerPrefs.GetInt(keys[i],0)==1?labels[i]+"  ·  DESBLOQUEADO\n":"🔒 "+labels[i]+"\n";AddMenuText(menuCard,text,24,new Vector2(0,55),new Vector2(700,300));CreateMenuButton("VOLVER",new Vector2(0,-220),ShowMainMenu);}
    void ShowCharacter(int index){characterPage=(index+5)%5;MenuHeader("GALERÍA DE PERSONAJES","Consulta cada personaje por separado.");AddFrameRect(menuCard,"Marco de retrato",new Vector2(0,110),new Vector2(164,260),new Color(.05f,.52f,.68f));var p=new GameObject("Retrato");p.transform.SetParent(menuCard,false);characterPortrait=p.AddComponent<Image>();characterPortrait.sprite=MakeSprite(characterPage);characterPortrait.preserveAspect=true;var pr=p.GetComponent<RectTransform>();pr.anchorMin=pr.anchorMax=new Vector2(.5f,.5f);pr.sizeDelta=new Vector2(148,244);pr.anchoredPosition=new Vector2(0,110);string[] details={"RATCHET DUNKOLD · RATÓN\nEstudiante. Chaqueta azul, camisa clara, lentes oscuros y cola larga.","FLAKY PEACEDAY · PINGÜINA\nEstudiante. Plumaje morado, gorro tejido rojo, mochila y uniforme escolar.","KHATERINE FIELDGAR · ZORRA\nEstudiante. Pelaje naranja, bufanda azul y uniforme universitario.","BERNIE HOPPER · CONEJO\nEstudiante. Pelaje claro, suéter rojo, mochila y orejas largas.","MS. BEATRIZ CLAWSTER · GATA\nProfesora. Gata negra, ojos amarillos, traje azul formal y mirada vigilante."};AddMenuText(menuCard,details[characterPage],20,new Vector2(0,-55),new Vector2(680,100));CreateMenuButton("◀",new Vector2(-190,-155),()=>ShowCharacter(characterPage-1)).GetComponent<RectTransform>().sizeDelta=new Vector2(100,54);CreateMenuButton("▶",new Vector2(190,-155),()=>ShowCharacter(characterPage+1)).GetComponent<RectTransform>().sizeDelta=new Vector2(100,54);CreateMenuButton("VOLVER",new Vector2(0,-230),ShowMainMenu).GetComponent<RectTransform>().sizeDelta=new Vector2(300,54);}
    void ShowCredits(){MenuHeader("CRÉDITOS","PASILLO 14");AddMenuText(menuCard,"Concepto y universo: equipo de Pasillo 14\n\nDiseño de personajes: referencia visual compartida por el equipo\n\nPrototipo, programación y escenario: proyecto Pasillo 14\n\nGracias por jugar y ayudar al equipo a entregar su proyecto.",20,new Vector2(0,45),new Vector2(680,300));CreateMenuButton("VOLVER",new Vector2(0,-210),ShowMainMenu);}
    void ShowPause(){MenuHeader("PAUSA","Tu equipo todavía te espera.");CreateMenuButton("CONTINUAR",new Vector2(0,75),()=>{paused=false;menuRoot.SetActive(false);if(hudRoot)hudRoot.SetActive(true);});CreateMenuButton("MENÚ PRINCIPAL",new Vector2(0,-15),ShowMainMenu);}
    void StartGame(){if(!player||!cam||!hud||!task||students[0]==null)InitializeFromScene();if(!player||!cam||!hud||!task){MenuHeader("NO SE PUDO INICIAR","Falta un objeto de la escena. Vuelve a generar la escena desde Pasillo14 > Crear escena jugable.");CreateMenuButton("VOLVER AL MENÚ",new Vector2(0,-80),ShowMainMenu);return;}handoff=0;lives=3;boost=0;alert=0;hitCooldown=0;playerHidden=false;hideTimeRemaining=0;ended=false;paused=false;gameStarted=true;message="Entrega el proyecto al siguiente compañero.";player=students[0];player.transform.position=new Vector3(-14,0,0);for(int i=1;i<4;i++)if(students[i])students[i].transform.position=relay[i-1];for(int i=0;i<guards.Count;i++){guards[i].transform.position=guardHome[i];guardChasing[i]=false;guardReturning[i]=false;guardIgnorePlayerUntil[i]=0;guardSearch[i]=0;}SetHidden(false);task.transform.position=player.transform.position+Vector3.up*1.55f;menuRoot.SetActive(false);if(hudRoot)hudRoot.SetActive(true);}
    void Update(){
        if(!player||!cam||!hud||!task)return;
        if(!gameStarted){if(Input.GetKeyDown(KeyCode.Return)||Input.GetKeyDown(KeyCode.KeypadEnter)||Input.GetKeyDown(KeyCode.Space))StartGame();else if(Input.GetKeyDown(KeyCode.Alpha1))ShowDifficulty();else if(Input.GetKeyDown(KeyCode.Alpha2))ShowAwards();else if(Input.GetKeyDown(KeyCode.Alpha3))ShowCharacter(0);else if(Input.GetKeyDown(KeyCode.Alpha4))ShowCredits();if(!gameStarted)return;}
        if(Input.GetKeyDown(KeyCode.Escape)){paused=!paused;if(paused)ShowPause();else menuRoot.SetActive(false);}if(paused||ended)return;
        if(hitCooldown>0)hitCooldown-=Time.deltaTime;
        if(Input.GetKeyDown(KeyCode.H)){if(playerHidden)SetHidden(false);else if(IsNearHideSpot())SetHidden(true);else message="Acércate a una marca REFUGIO para esconderte.";}
        if(playerHidden){hideTimeRemaining-=Time.deltaTime;if(hideTimeRemaining<=0){SetHidden(false);message="¡Se agotó el tiempo de escondite! Muévete.";}else{UpdateGuards();hud.text=$"PASILLO 14  ·  ESCONDIDO  ·  {Mathf.CeilToInt(hideTimeRemaining)} s  ·  H SALIR  ·  {(alert>0?"¡TE BUSCAN!":"BUSCANDO")}";return;}}
        float h=Input.GetAxisRaw("Horizontal"),vAxis=Input.GetAxisRaw("Vertical");if(Input.GetKey(KeyCode.A)||Input.GetKey(KeyCode.LeftArrow))h=-1;if(Input.GetKey(KeyCode.D)||Input.GetKey(KeyCode.RightArrow))h=1;if(Input.GetKey(KeyCode.S)||Input.GetKey(KeyCode.DownArrow))vAxis=-1;if(Input.GetKey(KeyCode.W)||Input.GetKey(KeyCode.UpArrow))vAxis=1;
        var move=new Vector3(h,0,vAxis).normalized;float moveSpeed=speed*(boost>0?1.7f:1);player.transform.position+=move*moveSpeed*Time.deltaTime;player.transform.position=new Vector3(Mathf.Clamp(player.transform.position.x,-15,15),0,Mathf.Clamp(player.transform.position.z,-4.8f,4.8f));if(boost>0)boost-=Time.deltaTime;
        if(Input.GetKeyDown(KeyCode.V))boost=10;if(Input.GetKeyDown(KeyCode.Space))ThrowDistraction();if(Input.GetKeyDown(KeyCode.E)&&handoff<3&&Vector3.Distance(player.transform.position,relay[handoff])<1.8f){handoff++;player=students[handoff];message=handoff<3?"¡Relevo! Sigue hasta el siguiente compañero.":"Último relevo: ¡el equipo tiene el proyecto!";if(handoff>=3){Win();return;}}
        UpdateGuards();task.transform.position=player.transform.position+Vector3.up*1.55f;hud.text=$"PASILLO 14  ·  {names[handoff]}  ·  RELEVOS {handoff}/3  ·  VIDAS {lives}  ·  {(alert>0?"¡EN PERSECUCIÓN!":"SIN DETECTAR")}  ·  WASD MOVER  ·  E RELEVO  ·  ESPACIO DISTRAER  ·  V VIVA 87  ·  {(IsNearHideSpot()?"H ESCONDERSE":"BUSCA REFUGIOS")}";
    }
    void ThrowDistraction(){var o=GameObject.CreatePrimitive(PrimitiveType.Sphere);o.name="Bola de papel";o.transform.localScale=Vector3.one*.2f;o.transform.position=player.transform.position+player.transform.forward*.8f+Vector3.up;o.GetComponent<Renderer>().material.color=Color.white;Destroy(o,2.5f);bool distracted=false;for(int i=0;i<guards.Count;i++)if(Vector3.Distance(guards[i].transform.position,player.transform.position)<8){guardChasing[i]=false;guardReturning[i]=false;guardSearch[i]=0;guards[i].transform.position=guardHome[i];distracted=true;}message=distracted?"¡Distracción! La profesora perdió tu rastro.":"Bola lanzada: acércate más a una profesora.";}
    void Win(){ended=true;gameStarted=false;string key=difficulty==Difficulty.Principiante?"Pasillo14_Plata":difficulty==Difficulty.Avanzado?"Pasillo14_Oro":"Pasillo14_Diamante";string trophy=difficulty==Difficulty.Principiante?"PLATA":difficulty==Difficulty.Avanzado?"ORO":"DIAMANTE";PlayerPrefs.SetInt(key,1);PlayerPrefs.Save();ShowResult("¡PROYECTO ENTREGADO!","¡El equipo completo está a salvo!\n\nTrofeo desbloqueado: "+trophy);}
    void Lose(){ended=true;gameStarted=false;int fails=PlayerPrefs.GetInt("Pasillo14_Fails",0)+1;PlayerPrefs.SetInt("Pasillo14_Fails",fails);bool unlocked=fails>=3;if(unlocked){PlayerPrefs.SetInt("Pasillo14_Consuelo",1);PlayerPrefs.Save();}ShowResult("TE ATRAPARON",unlocked?"Perdiste varias veces.\n\nTrofeo consuelo desbloqueado: SHREK EN BIKINI":"Perdiste las tres vidas.\n\nEl trofeo consuelo se desbloquea tras varios intentos.");}
    void ShowResult(string title,string details){if(hudRoot)hudRoot.SetActive(false);menuRoot.SetActive(true);MenuHeader(title,details);CreateMenuButton("VER PREMIOS",new Vector2(0,30),ShowAwards);CreateMenuButton("MENÚ PRINCIPAL",new Vector2(0,-65),ShowMainMenu);}
